const ingredients = {
 pollo:['Pechuga de pollo','g','Proteínas y lácteos'], atun:['Atún al natural escurrido','g','Proteínas y lácteos'], huevo:['Huevos','ud.','Proteínas y lácteos'], feta:['Queso feta','g','Proteínas y lácteos'], yogur:['Yogur natural','g','Proteínas y lácteos'],
 arroz:['Arroz integral','g','Cereales y despensa'], pasta:['Pasta integral','g','Cereales y despensa'], garbanzos:['Garbanzos cocidos','g','Cereales y despensa'], lentejas:['Lentejas cocidas','g','Cereales y despensa'], tortillas:['Tortillas de maíz','ud.','Cereales y despensa'], aceite:['Aceite de oliva','ml','Cereales y despensa'], sal:['Sal','g','Cereales y despensa'], pimienta:['Pimienta','g','Cereales y despensa'], comino:['Comino','g','Cereales y despensa'],
 tomate:['Tomate','g','Verduras y frescos'], pepino:['Pepino','g','Verduras y frescos'], espinaca:['Espinacas','g','Verduras y frescos'], calabacin:['Calabacín','g','Verduras y frescos'], cebolla:['Cebolla','g','Verduras y frescos'], zanahoria:['Zanahoria','g','Verduras y frescos'], pimiento:['Pimiento','g','Verduras y frescos'], patata:['Patata','g','Verduras y frescos'], limon:['Limón (zumo)','ml','Verduras y frescos'], ajo:['Ajo','dientes','Verduras y frescos']
};
const meals = [
 {day:'Lunes',name:'Bowl de pollo al limón',icon:'🥗',time:30,items:{pollo:150,arroz:70,tomate:100,pepino:100,limon:15,aceite:10,sal:1,pimienta:0.5},steps:['Cuece el arroz según el envase (aprox. 25–30 min).','Corta el tomate y el pepino. Cocina el pollo en una sartén con el aceite hasta que el centro alcance 74 °C.','Sirve todo en un bowl y aliña con limón, sal y pimienta.']},
 {day:'Martes',name:'Garbanzos con espinacas',icon:'🥘',time:25,items:{garbanzos:180,espinaca:100,tomate:150,cebolla:50,ajo:1,arroz:60,aceite:10,comino:1,sal:1},steps:['Cuece el arroz según el envase. Si usas el arroz reservado del lunes, recaliéntalo bien.','Sofríe la cebolla y el ajo picados con el aceite durante 5 min. Añade el tomate troceado y cocina 8 min.','Incorpora garbanzos escurridos, espinacas, comino y sal. Cocina 5 min y sirve con arroz.']},
 {day:'Miércoles',name:'Pasta con atún y calabacín',icon:'🍝',time:20,items:{pasta:80,atun:80,calabacin:150,tomate:150,ajo:1,aceite:10,sal:1,pimienta:0.5},steps:['Cuece la pasta según el envase y reserva un poco del agua de cocción.','Saltea el ajo y el calabacín con el aceite 5 min. Añade tomate troceado y cocina otros 6 min.','Añade el atún escurrido, la pasta, sal y pimienta. Mezcla con un chorrito del agua reservada.']},
 {day:'Jueves',name:'Ensalada tibia de lentejas',icon:'🥙',time:20,items:{lentejas:200,zanahoria:100,pepino:100,tomate:100,feta:40,limon:15,aceite:10,sal:1,pimienta:0.5},steps:['Corta la zanahoria en dados pequeños y cuécela 8–10 min. Escurre.','Enjuaga las lentejas y caliéntalas 2 min con un poco de agua. Escúrrelas.','Mezcla con pepino y tomate picados, zanahoria y feta. Aliña con aceite, limón, sal y pimienta.']},
 {day:'Viernes',name:'Tacos de pollo y pimientos',icon:'🌮',time:25,items:{pollo:150,tortillas:3,pimiento:150,cebolla:50,yogur:60,limon:10,aceite:10,comino:1,sal:1},steps:['Corta el pollo y las verduras en tiras. Saltea cebolla y pimiento con aceite 7 min.','Añade pollo, comino y sal. Cocina hasta que el pollo alcance 74 °C en el centro.','Calienta las tortillas. Rellena y acompaña con el yogur mezclado con el limón.']},
 {day:'Sábado',name:'Tortilla de patata y espinacas',icon:'🍳',time:30,items:{huevo:2,patata:200,espinaca:80,cebolla:50,tomate:100,aceite:15,sal:1,pimienta:0.5},steps:['Pela y corta la patata en dados pequeños. Cuécela en agua 10–12 min y escurre.','Saltea la cebolla con el aceite 5 min. Añade patata y espinacas, y cocina 2 min.','Bate los huevos con sal y pimienta y añádelos. Cuaja a fuego suave por ambos lados hasta que el huevo esté firme. Sirve con tomate.']},
 {day:'Domingo',name:'Verduras al horno con garbanzos',icon:'🥕',time:35,items:{garbanzos:180,calabacin:150,zanahoria:100,pimiento:150,feta:40,yogur:60,limon:10,aceite:10,comino:1,sal:1},steps:['Precalienta el horno a 200 °C. Corta las verduras en trozos pequeños y seca los garbanzos escurridos.','Mezcla con aceite, sal y comino. Hornea 25–30 min, removiendo a mitad de cocción.','Sirve con feta desmenuzado y una salsa de yogur con limón.']}
];
let state={bought:[],cooked:[]};
try { const saved=JSON.parse(localStorage.getItem('crymenu-v1')); if(saved && Array.isArray(saved.bought)&&Array.isArray(saved.cooked))state=saved; } catch{}
const totals={};meals.forEach(m=>Object.entries(m.items).forEach(([key,n])=>totals[key]=(totals[key]||0)+n));
const format=(n)=>Number(n.toFixed(1)).toLocaleString('es');
function save(){try{localStorage.setItem('crymenu-v1',JSON.stringify(state));}catch{toast('No se pudo guardar: el almacenamiento está deshabilitado.');}update();}
function update(){document.querySelector('#progress').textContent=`${state.cooked.length} de 7 preparados`;const n=Object.keys(totals).filter(k=>state.bought.includes(k)).length;document.querySelector('#shopping-progress').textContent=`${n} de ${Object.keys(totals).length} ingredientes listos`;document.querySelector('#nav-count').textContent=Object.keys(totals).length-n;document.querySelectorAll('[data-row]').forEach(r=>r.classList.toggle('done',state.cooked.includes(Number(r.dataset.row))));}
document.querySelector('#meals').innerHTML=meals.map((m,i)=>`<tr data-row="${i}"><td><div class="meal-title"><span class="meal-icon" aria-hidden="true">${m.icon}</span><div><b>${m.name}</b><small>◷ ${m.time} min · 1 porción</small></div></div></td><td><span class="day">${m.day}</span></td><td>${Object.entries(m.items).map(([k,n])=>`${format(n)} ${ingredients[k][1]} de ${ingredients[k][0].toLowerCase()}`).join(' · ')}</td><td><details><summary>Ver receta <span aria-hidden="true">↗</span></summary><ol>${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol></details><label class="prepared"><input type="checkbox" data-cooked="${i}" ${state.cooked.includes(i)?'checked':''}> Ya lo preparé</label></td></tr>`).join('');
const groups=['Verduras y frescos','Proteínas y lácteos','Cereales y despensa'];
document.querySelector('#shopping').innerHTML=groups.map((group,i)=>`<div class="shop-group"><h3>${['♧','◒','▤'][i]} &nbsp;${group}</h3>${Object.keys(totals).filter(k=>ingredients[k][2]===group).map(k=>`<label class="shop-item"><input type="checkbox" data-bought="${k}" ${state.bought.includes(k)?'checked':''}><span class="item-name">${ingredients[k][0]}</span><span class="quantity">${format(totals[k])} ${ingredients[k][1]}</span></label>`).join('')}${i===0?'<p class="note">50 ml de zumo ≈ 2 limones pequeños.</p>':''}</div>`).join('');
document.addEventListener('change',e=>{let prop,key;if(e.target.matches('[data-bought]')){prop='bought';key=e.target.dataset.bought;}else if(e.target.matches('[data-cooked]')){prop='cooked';key=Number(e.target.dataset.cooked);}else return;state[prop]=state[prop].filter(k=>k!==key);if(e.target.checked)state[prop].push(key);save();});
document.querySelector('#reset').onclick=()=>{state.bought=[];document.querySelectorAll('[data-bought]').forEach(el=>el.checked=false);save();};
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3500);}
document.querySelector('#copy').onclick=async()=>{const text='CRY MENÚ · Compra para 1 persona / 7 almuerzos\n\n'+groups.map(g=>g+'\n'+Object.keys(totals).filter(k=>ingredients[k][2]===g).map(k=>`${state.bought.includes(k)?'✓':'□'} ${ingredients[k][0]}: ${format(totals[k])} ${ingredients[k][1]}`).join('\n')).join('\n\n');try{await navigator.clipboard.writeText(text);toast('Lista copiada. ¡A por la compra!');}catch{const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='lista-compra.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Lista descargada en un archivo de texto.');}};
document.querySelector('#print').onclick=()=>{const details=[...document.querySelectorAll('details')];const previous=details.map(d=>d.open);details.forEach(d=>d.open=true);window.print();details.forEach((d,i)=>d.open=previous[i]);};update();
